use vstd::prelude::*;

verus! {
    // flipud takes a vector of f32 and returns a new vector
    // which is the reverse of the input.
    fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            // the result has the same length as the input
            result.len() == m.len(),
        ensures
            // for every valid index i, result[i] == m[m.len() - 1 - i]
            forall |i: usize|
                i < result.len() ==> result[i] == m[m.len() - 1 - i],
    {
        let n = m.len();
        let mut result: Vec<f32> = Vec::new();
        let mut i: usize = 0;

        // We build `result` by pushing in elements of `m` from the end to the front.
        while i < n
            invariant
                // 0 ≤ i ≤ n
                i <= n,
            invariant
                // result.len() tracks how many elements we've pushed so far
                result.len() == i,
            invariant
                // for each index j < result.len(), we've correctly reversed that prefix
                forall |j: usize|
                    j < result.len() ==>
                        result[j] == m[n - 1 - j],
            decreases
                // we make progress by increasing i
                n - i,
        {
            // safe because i < n implies n-1-i < n = m.len()
            let val: f32 = m.get(n - 1 - i);
            result.push(val);
            i = i + 1;
        }

        result
    }
}
